int sumar(int v[], int n) {
  if (n == 0) {
    return 0;
  }
  return v[n - 1] + sumar(v, n - 1);
}

int esta(int v[], int n, int valor) {
  if (n == 0) {
    return 0;
  }
  if (v[n - 1] == valor) {
    return 1;
  }
  return esta(v, n - 1, valor);
}

void mostrar(int v[], int n) {
  if (n == 0) {
    return;
  }
  printf("%d ", v[n - 1]);
  mostrar(v, n - 1);
}

int largo(char s[], int i) {
  if (s[i] == '\0') {
    return 0;
  }
  return 1 + largo(s, i + 1);
}

int contar(char s[], int i, char letra) {
  if (s[i] == '\0') {
    return 0;
  }
  if (s[i] == letra) {
    return 1 + contar(s, i + 1, letra);
  }
  return contar(s, i + 1, letra);
}

