int sumarRecursiva(int v[], int n) {
  if (n == 0) {
    return 0;
  }
  return v[n - 1] + sumarRecursiva(v, n - 1);
}

int sumarConCiclo(int v[], int n) {
  int total = 0;
  for (int i = 0; i < n; i++) {
    total = total + v[i];
  }
  return total;
}

